<script module lang="ts">
/**
 * Markdown, rendered through the vocabulary (`design/components/markdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotText, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBody from './MarkdownBody.svelte'
import Skeleton from '../structure/Skeleton.svelte'
import type { CitationSource } from './SourceList.svelte'

export type MarkdownSize = NonNullable<MarkdownProps['size']>

export interface MarkdownProps {
  /**
   * The markdown source received so far.
   */
  children: Snippet
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The reply's sources in numbered order, which turn each `[n]` in the prose into a Citation to
   * the nth source (without them, `[n]` stays text).
   */
  sources?: CitationSource[]
  /**
   * Whether more is coming, which renders unfinished constructs as text and shows a caret at the
   * end.
   */
  streaming?: boolean
}
</script>

<script lang="ts">
let { children, size = 'md', sources = (() => [])(), streaming = false }: MarkdownProps = $props()
const joined = joinSlot(undefined, () => ({ size: size }))
const childrenText = new SlotText(() => children)
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    class={styles.root}
    data-size={size}
    data-state={streaming ? 'streaming' : undefined}
    data-pending={(streaming && childrenText.current.trim() === '') ? '' : undefined}
    aria-busy={streaming ? true : undefined}
    data-member="markdown"
    >{#if streaming && childrenText.current.trim() === ''
      }<Skeleton shape="text" textStep={size} width={9}
    />{:else
      }<MarkdownBody source={childrenText.current} {size} {sources} {streaming}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
